// "Generated by an agent" reveals: a screenshot or photo appears the way an AI would build it. Dotted
// wireframes draw each UI block, a halftone of the image's own pixels fills in, then the real pixels
// resolve block by block (with an optional agent log typing alongside). Original Agentcut effect.
import { useLayoutEffect, useRef, useState } from "react";
import { Img, interpolate, useCurrentFrame, useDelayRender, useRemotionEnvironment } from "remotion";
import { usePlaneLayer } from "../cinematic/Cinematic";
import { alpha, FONTS, loadMotionFonts } from "../lib";

export interface GenerateRevealProps {
  /** Image URL (in scenes: asset("assets/…")). */
  src: string;
  /**
   * Size of the box in px (the image covers it). Inside a cinematic Screen use the Screen's own
   * `width` and `width / aspect`, so the build fills the screen exactly.
   */
  width: number;
  height: number;
  /**
   * The UI's blocks, [x, y, w, h] in fractions of the image, in build order (header, sidebar, cards…).
   * Leave out for photos: the whole image builds as one block. Values are clamped to the image.
   */
  boxes?: [number, number, number, number][];
  /** First frame of the build (local to the scene) and how long it takes. */
  from?: number;
  duration?: number;
  /** "ui": wireframe → halftone → pixels. "image": tone sketch → colour dots → photo. */
  mode?: "ui" | "image";
  /** Wireframe and cursor colour. */
  accent?: string;
  /** Dot pitch in px of the box (smaller = finer halftone). */
  dot?: number;
  /** Agent log lines typed while it builds (empty for none); one line per block reads best. */
  log?: string[];
  /** Where the log sits. */
  logPosition?: "top-left" | "bottom-left" | "top-right" | "bottom-right";
  radius?: number;
  /** Background behind the image while it builds. */
  background?: string;
  /**
   * Pixel ratio of the dots-and-wireframe canvas. Defaults to 2 in renders and exports (sharp under a
   * camera push-in) and 1 in the live preview. Lower it for very large boxes. The blurred and mirrored
   * copies a cinematic Plane draws always use 0.5 (and square dots): they're only seen soft.
   */
  resolution?: number;
}

interface Sampled {
  /** The sampling inputs these cells belong to. */
  key: string;
  cols: number;
  rows: number;
  /** r, g, b, luma per cell; null when the pixels can't be read (no CORS): no dotted fill then. */
  cells: Float32Array | null;
}

const ease = (k: number) => 1 - Math.pow(1 - Math.min(1, Math.max(0, k)), 3);
const win = (p: number, a: number, b: number) => Math.min(1, Math.max(0, (p - a) / Math.max(1e-6, b - a)));
const clamp01 = (v: number) => Math.min(1, Math.max(0, Number.isFinite(v) ? v : 0));
/** Frames the full image takes to cross-fade in over the per-block pixels once the build is done. */
const SETTLE_FRAMES = 10;
/** Largest canvas side, so a high `resolution` on a big box stays quick to draw and capture. */
const MAX_CANVAS = 4096;

/** Boxes clamped to the image; empty ones dropped (the whole image when none are left). */
function clampBoxes(boxes: GenerateRevealProps["boxes"]): [number, number, number, number][] {
  const out: [number, number, number, number][] = [];
  for (const [x, y, w, h] of boxes ?? []) {
    const x0 = clamp01(x);
    const y0 = clamp01(y);
    const x1 = clamp01(x + w);
    const y1 = clamp01(y + h);
    if (x1 - x0 > 1e-4 && y1 - y0 > 1e-4) out.push([x0, y0, x1 - x0, y1 - y0]);
  }
  return out.length ? out : [[0, 0, 1, 1]];
}

/** A screenshot or photo that builds itself on screen like an agent is generating it. */
export function GenerateReveal({
  src,
  width,
  height,
  boxes,
  from = 0,
  duration = 90,
  mode = "ui",
  accent = "#7c5cff",
  dot = 9,
  log = [],
  logPosition = "top-left",
  radius = 0,
  background = "transparent",
  resolution,
}: GenerateRevealProps) {
  const frame = useCurrentFrame();
  const env = useRemotionEnvironment();
  // Inside a Plane's lens-blur or reflection copy: the cheap drawing reads the same once blurred.
  const { copy } = usePlaneLayer();
  const canvas = useRef<HTMLCanvasElement>(null);
  const { delayRender, continueRender } = useDelayRender();
  const [sampled, setSampled] = useState<Sampled | null>(null);
  /** Releases the current sampling hold (idempotent); set by the sampling effect. */
  const releaseSample = useRef<(() => void) | null>(null);
  const blocks = clampBoxes(boxes);
  const p = interpolate(frame, [from, from + duration], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  // Once the build is done the full image fades in on top, so areas no box covers show too.
  const settle = interpolate(frame, [from + duration, from + duration + SETTLE_FRAMES], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const cols = Math.max(8, Math.round(width / dot));
  const rows = Math.max(6, Math.round(height / dot));
  const key = `${src}|${cols}|${rows}`;
  // Preview-only shortcut: the live player draws the canvas at 1x; captures and exports stay sharp.
  const preview = env.isPlayer && !env.isRendering;
  const ratio = copy ? 0.5 : Math.max(0.5, Math.min(resolution ?? (preview ? 1 : 2), MAX_CANVAS / Math.max(1, width, height)));
  const canvasW = Math.max(1, Math.round(width * ratio));
  const canvasH = Math.max(1, Math.round(height * ratio));

  // Sample the image once on a coarse grid: the halftone is made of its own pixels. The hold is taken
  // in a layout effect (on the first commit, before a capture looks for holds, and never in a render
  // React may discard) and released by the first draw with these samples, or by cleanup (unmount,
  // StrictMode's second mount, new inputs).
  useLayoutEffect(() => {
    let alive = true;
    let released = false;
    const handle = delayRender(`Sampling ${src} for GenerateReveal`);
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    releaseSample.current = release;
    const done = (cells: Float32Array | null) => {
      if (alive) setSampled({ key, cols, rows, cells });
    };
    // A decorative layer never aborts the render: without readable pixels it skips the dotted fill
    // (wireframes, log and the real <Img> reveal still play; a missing image fails in that <Img>).
    const degrade = (reason: string) => {
      console.warn(`GenerateReveal: ${reason} for ${src}; drawing it without the dotted fill.`);
      done(null);
    };
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => {
      if (!alive) return;
      const c = document.createElement("canvas");
      c.width = cols;
      c.height = rows;
      const ctx = c.getContext("2d");
      if (!ctx) return degrade("no 2D canvas");
      try {
        // Cover the box like the <Img> below.
        const s = Math.max(cols / image.naturalWidth, rows / image.naturalHeight);
        const w = image.naturalWidth * s;
        const h = image.naturalHeight * s;
        ctx.drawImage(image, (cols - w) / 2, (rows - h) / 2, w, h);
        // A SecurityError here means the server sent no CORS headers (the canvas is tainted).
        const data = ctx.getImageData(0, 0, cols, rows).data;
        const cells = new Float32Array(cols * rows * 4);
        for (let i = 0; i < cols * rows; i++) {
          const r = data[i * 4];
          const g = data[i * 4 + 1];
          const b = data[i * 4 + 2];
          cells.set([r, g, b, (0.299 * r + 0.587 * g + 0.114 * b) / 255], i * 4);
        }
        done(cells);
      } catch (error) {
        degrade(`couldn't read the pixels (${error instanceof Error ? error.message : String(error)})`);
      }
    };
    image.onerror = () => {
      if (alive) degrade("couldn't load the image with CORS");
    };
    image.src = src;
    return () => {
      alive = false;
      image.onload = null;
      image.onerror = null;
      if (releaseSample.current === release) releaseSample.current = null;
      release();
    };
  }, [key, src, cols, rows, delayRender, continueRender]);

  // The log's font (Geist Mono) is a library font that scenes don't load: hold until it's in.
  const hasLog = log.length > 0;
  useLayoutEffect(() => {
    if (!hasLog) return;
    let alive = true;
    let released = false;
    const handle = delayRender("Loading the GenerateReveal log font");
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    // loadMotionFonts resolves even when the network fails (the text falls back), so this always ends.
    loadMotionFonts()
      .then(() => document.fonts.load(`500 16px ${FONTS.mono}`))
      .catch(() => undefined)
      .then(() => {
        if (alive) release();
      });
    return () => {
      alive = false;
      release();
    };
  }, [hasLog, delayRender, continueRender]);

  // Timing per block: each block runs wire → dots → pixels, staggered in build order.
  const n = blocks.length;
  const stagger = n > 1 ? 0.55 / (n - 1) : 0;
  const span = 0.45;
  const stage = (i: number) => {
    const q = win(p, i * stagger, i * stagger + span);
    return { wire: ease(win(q, 0, 0.35)), dots: ease(win(q, 0.2, 0.6)), pixels: ease(win(q, 0.55, 1)), q };
  };

  useLayoutEffect(() => {
    const ready = sampled?.key === key;
    const c = canvas.current;
    const ctx = c?.getContext("2d");
    if (c && ctx) {
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      ctx.clearRect(0, 0, width, height);
      const cells = ready && sampled ? sampled.cells : null;
      const cw = width / cols;
      const ch = height / rows;
      blocks.forEach(([bx, by, bw, bh], i) => {
        const st = stage(i);
        const x0 = bx * width;
        const y0 = by * height;
        const w = bw * width;
        const h = bh * height;
        // Halftone of the block's own pixels, sweeping top to bottom, then fading as the pixels arrive.
        const dotsAlpha = st.dots * (1 - st.pixels);
        if (cells && dotsAlpha > 0.01) {
          const c0 = Math.max(0, Math.floor(bx * cols));
          const c1 = Math.min(cols, Math.ceil((bx + bw) * cols));
          const r0 = Math.max(0, Math.floor(by * rows));
          const r1 = Math.min(rows, Math.ceil((by + bh) * rows));
          for (let r = r0; r < r1; r++) {
            const sweep = Math.min(1, Math.max(0, st.dots * 1.3 - ((r - r0) / Math.max(1, r1 - r0)) * 0.3));
            if (sweep <= 0) continue;
            for (let col = c0; col < c1; col++) {
              const k = (r * cols + col) * 4;
              const [R, G, B, L] = [cells[k], cells[k + 1], cells[k + 2], cells[k + 3]];
              // Light UIs: ink where it's dark; dark UIs: ink where it's light.
              // Every cell gets a dot (a readable dotted fill); contrast against the page makes it bigger.
              const ink = 0.22 + 0.78 * Math.abs(L - (L > 0.5 ? 1 : 0));
              const colour = mode === "image" ? st.dots : Math.max(0, st.dots - 0.4) / 0.6;
              const mono = mode === "image" ? 1 - st.dots : 1;
              const tone = Math.round(255 * (L > 0.5 ? 0.15 : 0.9));
              const cr = Math.round(R * colour + tone * (1 - colour));
              const cg = Math.round(G * colour + tone * (1 - colour));
              const cb = Math.round(B * colour + tone * (1 - colour));
              const radius = Math.max(0.4, Math.min(cw, ch) * 0.5 * Math.sqrt(Math.max(0.08, ink)) * sweep);
              // Empty page reads as the agent's dotted fill (accent); content keeps its own colours.
              ctx.fillStyle =
                mode === "ui" && Math.abs(L - (cells[3] ?? L)) < 0.06
                  ? alpha(accent, dotsAlpha * 0.45)
                  : `rgba(${cr},${cg},${cb},${dotsAlpha * (0.55 + 0.45 * mono)})`;
              if (copy) {
                // A square of the same area: far cheaper than an arc, identical once blurred.
                const side = radius * Math.sqrt(Math.PI);
                ctx.fillRect((col + 0.5) * cw - side / 2, (r + 0.5) * ch - side / 2, side, side);
              } else {
                ctx.beginPath();
                ctx.arc((col + 0.5) * cw, (r + 0.5) * ch, radius, 0, Math.PI * 2);
                ctx.fill();
              }
            }
          }
        }
        // Dotted wireframe drawn around the block, then fading once the pixels land.
        if (mode === "ui" && st.wire > 0 && st.pixels < 1) {
          const per = 2 * (w + h);
          ctx.save();
          ctx.strokeStyle = alpha(accent, 0.95 * (1 - st.pixels));
          ctx.lineWidth = Math.max(2, dot * 0.32);
          ctx.lineCap = "round";
          // Reveal the dotted outline along its perimeter.
          ctx.setLineDash([0.1, dot * 0.8]);
          const length = per * st.wire;
          ctx.beginPath();
          let left = length;
          const pts: [number, number][] = [
            [x0 + 2, y0 + 2],
            [x0 + w - 2, y0 + 2],
            [x0 + w - 2, y0 + h - 2],
            [x0 + 2, y0 + h - 2],
            [x0 + 2, y0 + 2],
          ];
          ctx.moveTo(pts[0][0], pts[0][1]);
          let cursor = pts[0];
          for (let s = 1; s < pts.length && left > 0; s++) {
            const [ax, ay] = pts[s - 1];
            const [bx2, by2] = pts[s];
            const seg = Math.hypot(bx2 - ax, by2 - ay);
            const k = Math.min(1, left / seg);
            cursor = [ax + (bx2 - ax) * k, ay + (by2 - ay) * k];
            ctx.lineTo(cursor[0], cursor[1]);
            left -= seg;
          }
          ctx.stroke();
          ctx.restore();
          // The "agent's cursor" at the drawing tip.
          if (st.wire < 1) {
            ctx.fillStyle = accent;
            ctx.beginPath();
            ctx.arc(cursor[0], cursor[1], Math.max(3, dot * 0.45), 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = alpha(accent, 0.25);
            ctx.beginPath();
            ctx.arc(cursor[0], cursor[1], Math.max(8, dot * 1.3), 0, Math.PI * 2);
            ctx.fill();
          }
        }
      });
    }
    // The first frame drawn with these samples (or knowing there are none) releases the render hold.
    if (ready) releaseSample.current?.();
  });

  const logLines = log.slice(0, Math.max(0, n === 1 ? log.length : n));
  const [vertical, horizontal] = logPosition.split("-") as ["top" | "bottom", "left" | "right"];
  const imgStyle = { width: "100%", height: "100%", objectFit: "cover", display: "block" } as const;

  return (
    <div style={{ position: "relative", width, height, borderRadius: radius, overflow: "hidden", background }}>
      {settle < 1
        ? blocks.map(([bx, by, bw, bh], i) => {
            const st = stage(i);
            if (st.pixels <= 0) return null;
            // The real pixels of this block resolve from soft to sharp.
            const clip = `inset(${(by * 100).toFixed(3)}% ${((1 - bx - bw) * 100).toFixed(3)}% ${((1 - by - bh) * 100).toFixed(3)}% ${(bx * 100).toFixed(3)}%)`;
            const blur = (1 - st.pixels) * 10;
            return (
              <div key={i} style={{ position: "absolute", inset: 0, clipPath: clip, opacity: st.pixels }}>
                <Img src={src} style={{ ...imgStyle, filter: blur > 0.3 ? `blur(${blur.toFixed(2)}px)` : undefined }} />
              </div>
            );
          })
        : null}
      {/* The end state is exactly the screenshot: one unclipped image, the per-block copies dropped. */}
      {settle > 0 ? <Img src={src} style={{ ...imgStyle, position: "absolute", inset: 0, opacity: settle }} /> : null}
      <canvas ref={canvas} width={canvasW} height={canvasH} style={{ position: "absolute", left: 0, top: 0, width, height }} />
      {logLines.length ? (
        <div
          style={{
            position: "absolute",
            [vertical]: Math.round(height * 0.04),
            [horizontal]: Math.round(width * 0.03),
            maxWidth: width * 0.5,
            padding: `${dot * 1.2}px ${dot * 1.6}px`,
            borderRadius: dot * 1.2,
            background: "rgba(12,12,16,0.82)",
            border: `1px solid ${alpha(accent, 0.5)}`,
            color: "#e7e7ee",
            font: `500 ${Math.max(11, Math.round(height * 0.022))}px ${FONTS.mono}`,
            lineHeight: 1.5,
            opacity: ease(win(p, 0, 0.06)) * (1 - ease(win(p, 0.94, 1))),
          }}
        >
          {logLines.map((line, i) => {
            const st = n === 1 ? { q: win(p, (i / logLines.length) * 0.8, ((i + 1) / logLines.length) * 0.8) } : stage(i);
            const typed = Math.round(line.length * win(st.q, 0, 0.4));
            if (st.q <= 0) return null;
            const done = st.q >= 1;
            return (
              <div key={i} style={{ whiteSpace: "nowrap", overflow: "hidden" }}>
                <span style={{ color: done ? accent : alpha("#e7e7ee", 0.5) }}>{done ? "✓ " : "› "}</span>
                {line.slice(0, typed)}
                {!done && typed < line.length ? <span style={{ color: accent }}>▍</span> : null}
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}
